   * @param candidate_readiness payload for data port candidate_readiness
   * @param dock_assessment payload for data port dock_assessment
   * @param selected_intent payload for data port selected_intent
   */
  def put_concrete_inputs(request_fact : Factory_Dispatch_Coordinator.Qualified_Request_Fact,
                          candidate_readiness : Factory_Dispatch_Coordinator.Candidate_Inventory_Readiness,
                          dock_assessment : Factory_Dispatch_Coordinator.Dock_Assessment.Type,
                          selected_intent : Factory_Dispatch_Coordinator.Selected_Intent.Type): Unit = {
    put_request_fact(request_fact)
    put_candidate_readiness(candidate_readiness)
    put_dock_assessment(dock_assessment)
    put_selected_intent(selected_intent)
  }


  /** helper function to check Release_Arbiter_dispatch_coordinator_process_release_arbiter's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param dispatch_decision method that will be called with the value of the outgoing data
   *        port 'dispatch_decision'.
   * @param decision_reason method that will be called with the value of the outgoing data
   *        port 'decision_reason'.
   */
  def check_concrete_output(dispatch_decision: Factory_Dispatch_Coordinator.Dispatch_Decision => B,
                            decision_reason: Factory_Dispatch_Coordinator.Decision_Reason.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val dispatch_decisionValue: Factory_Dispatch_Coordinator.Dispatch_Decision = get_dispatch_decision().get
    if(!dispatch_decision(dispatch_decisionValue)) {
      testFailures = testFailures :+ st"'dispatch_decision' did not match expected: value of the outgoing data port is ${dispatch_decisionValue}"
    }
    val decision_reasonValue: Factory_Dispatch_Coordinator.Decision_Reason.Type = get_decision_reason().get
    if(!decision_reason(decision_reasonValue)) {
      testFailures = testFailures :+ st"'decision_reason' did not match expected: value of the outgoing data port is ${decision_reasonValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


